                    inclusive: true,
                    message: "Too many items 😡",
                    input: ctx.value
                });
            }
            if (ctx.value.length !== new Set(ctx.value).size) {
                ctx.issues.push({
                    code: "custom",
                    message: `No duplicates allowed.`,
                    input: ctx.value
                });
            }
        });

        // valid array
        assert.doesNotThrow(() => {
            UniqueStringArray.parse(["a", "b", "c"]);
        }, "Valid unique array should not throw");

